from PIL import Image
import os
FX = os.path.dirname(__file__)
F = {
 '0':[" ### ","#   #","#  ##","# # #","##  #","#   #"," ### "],
 '1':["  #  "," ##  ","  #  ","  #  ","  #  ","  #  "," ### "],
 '2':[" ### ","#   #","    #","   # ","  #  "," #   ","#####"],
 '3':[" ### ","#   #","    #","  ## ","    #","#   #"," ### "],
 '4':["   # ","  ## "," # # ","#  # ","#####","   # ","   # "],
 '5':["#####","#    ","#### ","    #","    #","#   #"," ### "],
 '8':[" ### ","#   #","#   #"," ### ","#   #","#   #"," ### "],
 '+':["     ","  #  ","  #  ","#####","  #  ","  #  ","     "],
 '-':["     ","     ","     ","#####","     ","     ","     "],
 '*':["     ","# # #"," ### ","#####"," ### ","# # #","     "],
 '/':["    #","    #","   # ","  #  "," #   ","#    ","#    "],
 '(':["  ## "," #   "," #   "," #   "," #   "," #   ","  ## "],
 ')':[" ##  ","   # ","   # ","   # ","   # ","   # "," ##  "],
 'a':["     "," ### ","    #"," ####","#   #","#   #"," ####"],
 'b':["#    ","#    ","#### ","#   #","#   #","#   #","#### "],
 'c':["     ","     "," ####","#    ","#    ","#    "," ####"],
 'x':["     ","     ","#   #"," # # ","  #  "," # # ","#   #"],
}
def render(text, scale=1):
    w = len(text)*6+1; h=7
    img = Image.new("L",(w*scale,h*scale),255)
    px = img.load()
    for i,ch in enumerate(text):
        g = F.get(ch)
        if not g: continue
        for y in range(7):
            for c in range(5):
                if g[y][c]=='#':
                    for dy in range(scale):
                        for dx in range(scale):
                            px[(i*6+c)*scale+dx, y*scale+dy]=0
    return img
render("a/(b*c)-1").save(os.path.join(FX,"eq1.png"))
render("(a+b)/c", scale=3).save(os.path.join(FX,"eq2.png"))
print("png fixtures:", [f for f in os.listdir(FX) if f.endswith(".png")])
